import 'package:flutter/material.dart';
import '../services/admin_api.dart';
class DashboardScreen extends StatefulWidget{final VoidCallback onLogout;const DashboardScreen({super.key,required this.onLogout});@override State<DashboardScreen> createState()=>_DashboardScreenState();}
