 @override Widget build(BuildContext context){final m=(data?['metrics'] as Map<String,dynamic>?)??{};final q=(data?['queues'] as Map<String,dynamic>?)??{};return Scaffold(appBar:AppBar(title:const Text('Owner Control Centre'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh)),IconButton(onPressed:widget.onLogout,icon:const Icon(Icons.logout))]),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[const Text('KAAMDAAR OVERVIEW',style:TextStyle(fontWeight:FontWeight.w900,letterSpacing:1,color:Color(0xFF0B2240))),const SizedBox(height:5),const Text('Live platform snapshot',style:TextStyle(color:Colors.black54,fontSize:12)),const SizedBox(height:16),if(loading)const LinearProgressIndicator(),if(error.isNotEmpty)Card(child:Padding(padding:const EdgeInsets.all(14),child:Text(error,style:const TextStyle(color:Colors.red)))),if(data!=null)...[GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,childAspectRatio:1.6,mainAxisSpacing:6,crossAxisSpacing:6,children:[metric('Customers',m['customers']??0,Icons.people),metric('Providers',m['providers']??0,Icons.engineering),metric('Online providers',m['onlineProviders']??0,Icons.location_on),metric('Admins',m['activeAdmins']??0,Icons.admin_panel_settings),metric('Bookings',m['bookings']??0,Icons.book_online),metric('Active bookings',m['live']??0,Icons.pending_actions),metric('Completed',m['completed']??0,Icons.task_alt),metric('Cancelled',m['cancelled']??0,Icons.cancel),metric('Revenue',money(m['revenue']),Icons.currency_rupee),metric('Commission',money(m['commission']),Icons.account_balance_wallet)]),const SizedBox(height:18),const Text('PENDING ACTIONS',style:TextStyle(fontWeight:FontWeight.w900,color:Color(0xFF0B2240))),metric('Pending KYC',q['pendingKyc']??0,Icons.verified_user),metric('Pending payments',q['pendingPayments']??0,Icons.payments),metric('Open complaints',q['pendingComplaints']??0,Icons.support_agent),metric('Pending payouts',q['pendingPayouts']??0,Icons.account_balance),const SizedBox(height:18),const Text('MANAGEMENT MODULES',style:TextStyle(fontWeight:FontWeight.w900,color:Color(0xFF0B2240))),const Wrap(spacing:8,runSpacing:8,children:[_Chip('Admins',Icons.admin_panel_settings),_Chip('Customers',Icons.people),_Chip('Providers',Icons.engineering),_Chip('Bookings',Icons.book_online),_Chip('Live tracking',Icons.map),_Chip('Payments',Icons.payments),_Chip('Complaints',Icons.support_agent),_Chip('Notifications',Icons.notifications),_Chip('Reports',Icons.bar_chart)])],if(data==null&&!loading&&error.isEmpty)const Text('No dashboard data available.'),const SizedBox(height:24),const Text('Kaamdaar · Owner-only access',textAlign:TextAlign.center,style:TextStyle(color:Colors.black45,fontSize:11))])));}
}
class _Chip extends StatelessWidget{final String label;final IconData icon;const _Chip(this.label,this.icon);@override Widget build(BuildContext context)=>Chip(avatar:Icon(icon,size:17,color:const Color(0xFF0B2240)),label:Text(label));}